 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Pays a payment order: validates account type, order and funds, computes tariff, commission and total, debits the account (and the commission when charged separately) and marks the order as paid, all in one transaction. Returns the legacy status, the movement and the message on every path.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_tipo_cuenta"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "@i_cuenta"
    },
    {
     "name": "amount",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "@i_valor"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_canal"
    },
    {
     "name": "processDate",
     "type": "timestamp(local)",
     "column": null,
     "legacy": "@i_fecha_proceso"
    }
   ],
   "outputs": [
    {
     "name": "movementId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_movimiento"
    },
    {
     "name": "message",
     "type": "text(var,120,iso8859-1)",
     "column": null,
     "legacy": "@o_mensaje"
    },
    {
     "name": "status",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "return"
    }
   ],
   "errors": [
    {
     "code": "DEBIT_FAILED",
     "legacy_code": "50005",
     "message": "ERROR EN DEBITO"
    },
    {
     "code": "COMMISSION_FAILED",
     "legacy_code": "50006",
     "message": "ERROR EN COMISION"
    },
    {
     "code": "ORDER_UPDATE_FAILED",
     "legacy_code": "50007",
     "message": "ERROR ACTUALIZANDO ORDEN"
    }
   ],
   "ports": [
    "PaymentOrderRepository",
    "CompanyTariffRepository",
    "ServiceCatalogRepository",
    "AccountRepository",
    "DebitGateway",
    "UnitOfWork"
   ],
   "http_method": "POST",
   "path": "/payment-orders/pay",
   "legacy_program": "dbo.sp_pago_orden",
   "unit_of_work": {
    "begins_at": 108,
    "commits_at": 161,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 119,
      "outcome": "DEBIT_FAILED"
     },
     {
      "legacy_line": 136,
      "outcome": "COMMISSION_FAILED"
     },
     {
      "legacy_line": 155,
      "outcome": "ORDER_UPDATE_FAILED"
     }
    ]
   },
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Status returned as data, not as exceptions",
   "context": "The legacy procedure returns @w_error as its return status on every error exit and still fills @o_mensaje (and @o_movimiento when the debit already ran).",
   "decision": "PayOrder returns status (legacy 'return'), message and movementId on every path (0 and 'PAGO REALIZADO' on success; 50001..50007 with the legacy message otherwise). The validation exits (50001 to 50004) are plain returned data and are not listed as errors. The three rollback exits (50005, 50006, 50007) are declared as errors of the use case (DEBIT_FAILED, COMMISSION_FAILED, ORDER_UPDATE_FAILED) only so that each rollback point of the unit of work has a named outcome. The service still undoes the transaction and returns the legacy status, message and outputs.",
   "consequences": "Callers, including the golden master replay, read the status and message from the response. The HTTP call succeeds even when the payment is rejected."
  },
  {
   "title": "Explicit transaction through the UnitOfWork port",
   "context": "The legacy opens the transaction just before the first debit (line 108), undoes it at lines 119, 136 and 155 and commits at line 161. The validations before line 108 run outside any transaction.",
   "decision": "The service calls UnitOfWork.begin() just before the order debit, rollback() at each of the three failure points and commit() after the order update. There are no savepoints. Validations before begin() do not open or roll back anything.",
   "consequences": "The debit, the separate commission debit and the order update are atomic in the target as in the legacy. The debit gateway has to take part in the same transaction."
  },
  {
   "title": "Migration to the target database",
   "context": "Data strategy is migration: the tables of pg_orden, ad_tarifa_empresa, ad_servicio and ct_cuenta move to the target PostgreSQL database with snake_case names.",
   "decision": "Four entities map those tables. The debit program db_cuentas..sp_debito is reached through the DebitGateway port (two methods, with the order and the commission references), with its return status mapped as 'return' and the movement as @o_secuencial.",
   "consequences": "The gateway implementation must keep the debit atomic with the order update in the target database."
  },
  {
   "title": "Calculation fidelity",
   "context": "The legacy uses money (4 decimals) and round(x/2, 2).",
   "decision": "All amounts are decimal(19,4). The WEB commission is the tariff divided by 2 rounded to 2 decimals half-up (away from zero), as Sybase round does. A missing tariff becomes 0. With no company tariff the separate-charge flag is 'N'. If no service row exists either, the tariff is 0 and the commission is added to the debit. NOMINA forces the commission to 0 after the channel rule.",
   "consequences": "5.01 on WEB gives 2.51 (2.505 rounded half-up)."
  },
  {
   "title": "Funds check with a missing account",
   "context": "If the account is not found, @w_saldo stays NULL and the legacy comparison is unknown, so the funds check does not reject and the sp_debito call decides.",
   "decision": "The same behaviour is kept: when AccountRepository returns no account the funds check is skipped and the debit is attempted.",
   "consequences": "A non-existent account ends with 50005 from the debit instead of 50004."
  },
  {
   "title": "Error-logging infrastructure is not translated",
   "context": "The ERROR label calls cobis..sp_cerror to register the error.",
   "decision": "sp_cerror is not ported; the status and message are returned in the response and the framework logs.",
   "consequences": "The central error table of the legacy is not fed by the new service."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "migration"
}

